#include <ctype.h>
#include <dirent.h>
#include <getopt.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>
// Feel free to change the data structures generated by AI.

#define MAX_SYSCALLS 1024
#define TOP_N 5

typedef struct {
    char name[64];
    double time;
    double ratio; // percentage of total time
} syscall_stat;

typedef struct {
    syscall_stat stats[MAX_SYSCALLS];
    int count;
    double total_time;
} syscall_stats;

int parse_strace_line(char *line, char *syscall_name, double *time) {
    if (!line || !syscall_name || !time)
        return -1;

    char *s = line;
    while (*s && isspace((unsigned char)*s))
        s++;

    char *lp = strchr(s, '(');
    char *rp = strrchr(s, ')');
    if (!lp || !rp || lp >= rp)
        return -1;

    char *name_end = lp;
    while (name_end > s && isspace((unsigned char)name_end[-1]))
        name_end--;

    size_t name_len = (size_t)(name_end - s);
    if (name_len == 0)
        return -1;

    memcpy(syscall_name, s, name_len);
    syscall_name[name_len] = '\0';

    char *lt = strchr(rp, '<');
    char *gt = lt ? strchr(lt, '>') : NULL;
    if (!lt || !gt || lt >= gt)
        return -1;

    char tmp[64];
    size_t dur_len = (size_t)(gt - lt - 1);
    if (dur_len == 0 || dur_len >= sizeof(tmp))
        return -1;

    memcpy(tmp, lt + 1, dur_len);
    tmp[dur_len] = '\0';

    char *end = NULL;
    *time = strtod(tmp, &end);
    if (end == tmp)
        return -1;

    return 0;
}

void add_syscall(syscall_stats *stats, const char *name, double time) {
    for (int i = 0; i < stats->count; i++) {
        if (strcmp(stats->stats[i].name, name) == 0) {
            stats->stats[i].time += time;
            stats->total_time += time;
            return;
        }
    }

    if (stats->count >= MAX_SYSCALLS) {
        return -1;
    }

    strcpy(stats->stats[stats->count].name, name);
    stats->stats[stats->count].time = time;
    stats->count++;
    stats->total_time += time;
}

static long diff_ms(const struct timespec *start, const struct timespec *end) {
    long seconds = end->tv_sec - start->tv_sec;
    long nanoseconds = end->tv_nsec - start->tv_nsec;
    return seconds * 1000 + nanoseconds / 1000000;
}

void compare_ratio(const void *a, const void *b) {
    const syscall_stat *sa = (const syscall_stat *)a;
    const syscall_stat *sb = (const syscall_stat *)b;
    return (sb->ratio > sa->ratio) - (sb->ratio < sa->ratio);
}

void print_top_syscalls(syscall_stats *stats, int n) {
    if (stats->count == 0) {
        printf("No syscalls recorded yet.\n");
        return;
    }

    // calc ratio and sort
    for (int i = 0; i < stats->count; i++) {
        double ratio = (stats->stats[i].time / stats->total_time) * 100;
        stats->stats[i].ratio = ratio;
    }
    // qsort
    qsort(stats->stats, stats->count, sizeof(syscall_stat), compare_ratio);

    // print top n
    for (int i = 0; i < n && i < stats->count; i++) {
        const char *syscall_name = stats->stats[i].name;
        double ratio = stats->stats[i].ratio;

        printf("%s (%.2f%%)\n", syscall_name, ratio);
    }
}

int main(int argc, char *argv[]) {

    if (argc < 2) {
        fprintf(stderr, "usage: %s command [args...]\n", argv[0]);
        return EXIT_FAILURE;
    }

    char **exec_argv = calloc(argc + 2, sizeof(char *));
    if (exec_argv == NULL) {
        perror("calloc");
        return EXIT_FAILURE;
    }
    exec_argv[0] = "strace";
    exec_argv[1] = "-T";

    char *exec_envp[] = {
        "PATH=/usr/local/bin:/usr/bin:/bin",
        NULL,
    };

    for (int i = 1; i < argc; i++) {
        exec_argv[i + 1] = argv[i];
    }
    exec_argv[argc + 1] = NULL;

    for (int i = 0; i < argc + 2; i++) {
        printf("exec_argv[%d]: %s\n", i, exec_argv[i]);
    }

    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        exit(EXIT_FAILURE);
    }

    pid_t pid = fork();

    if (pid == 0) {
        close(pipefd[0]);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[1]);

        execve("/usr/bin/strace", exec_argv, exec_envp);
        perror(argv[0]);
        exit(EXIT_FAILURE);

    } else if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }

    close(pipefd[1]);
    dup2(pipefd[0], STDIN_FILENO);
    close(pipefd[0]);

    FILE *in = fdopen(STDIN_FILENO, "r");
    char line[4096];

    syscall_stats stats = {0};

    struct timespec last_print;
    clock_gettime(CLOCK_MONOTONIC, &last_print);

    while (fgets(line, sizeof(line), in) != NULL) {
        printf("line: %s", line);
        syscall_stat syscall_stat = {0};

        if (parse_strace_line(line, syscall_stat.name, &syscall_stat.time) ==
            0) {
            // printf("syscall: %s, time: %f\n", syscall_stat.name,
            //        syscall_stat.time);
            add_syscall(&stats, syscall_stat.name, syscall_stat.time);

            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if (diff_ms(&last_print, &now) >= 1000) {
                print_top_syscalls(&stats, TOP_N);
                last_print = now;
            }
        }
    }

    return 0;
}
